using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// Z80 转译器
    /// </summary>
    public class TranslatorZ80 : Translator8bit
    {
        public override string ARCH_NAME => "Z80";
        protected override string CallMnemonic => "CALL";

        // Z80 中断上下文
        private static readonly string[] Z80Ctx = { "af", "bc", "de", "hl", "ix", "iy" };
        protected override string[] ContextRegNames() => Z80Ctx;
        protected override string NativeInt(int vector) => $"rst {vector:X2}h";
        protected override string NativeIret() => "reti";
        protected override string NativeCli() => "di";
        protected override string NativeSti() => "ei";
        protected override void EmitSaveContext()
        {
            foreach (var r in ContextRegNames())
                Emit($"        push {r}");
        }
        protected override void EmitRestoreContext()
        {
            var regs = ContextRegNames();
            for (int i = regs.Length - 1; i >= 0; i--)
                Emit($"        pop {regs[i]}");
        }

        private readonly Dictionary<int, string> REGISTER_MAP = new Dictionary<int, string>
        {
            { 0, "A" },
            { 1, "B" },
            { 2, "C" },
            { 3, "D" },
            { 4, "E" },
            { 5, "H" },
            { 6, "L" }
        };

        // VML 是32位指令集，Z80 是8位架构（有16位寄存器对）
        // 虚拟寄存器映射到内存：R0-R15 每个占4字节
        // 使用 HL 作为内存指针，IX/IY 作为辅助寄存器
        private const string VR_BASE = "8000H";  // 虚拟寄存器起始地址（外部RAM）

        // 获取虚拟寄存器的内存偏移
        private string GetRegOffset(int regNum) => $"{(regNum * 4):X4}H";

        public TranslatorZ80(VmlProgram vmlProgram) : base(vmlProgram) { }

        protected override void EmitHeader()
        {
            Emit("; Z80 Assembly - Translated from VML");
            Emit("; Generated by VML Translator");
            Emit("");
            Emit("        .area   _CODE");
            Emit("");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("");
                Emit("        .area   _DATA");
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (value is string strValue)
                    {
                        string escaped = strValue.Replace("\\", "\\\\").Replace("\"", "\\\"");
                        Emit($"{name}:");
                        Emit($"\t.ascii  \"{escaped}\"");
                        Emit("\t.db\t0");
                    }
                    else if (value is System.Collections.IList listValue)
                    {
                        var vals = new List<string>();
                        foreach (var item in listValue)
                        {
                            vals.Add($"0x{Convert.ToInt32(item):X2}");
                        }
                        Emit($"{name}:");
                        Emit($"\t.db\t{string.Join(", ", vals)}");
                    }
                    else if (int.TryParse(value.ToString(), out int intValue))
                    {
                        Emit($"{name}:");
                        Emit($"\t.dw\t0x{intValue:X4}");
                    }
                }
            }
        }

        protected override void EmitCode()
        {
            Emit("");
            Emit("        .area   _CODE");
            foreach (var instr in VmlProgram.Instructions)
            {
                if (!string.IsNullOrEmpty(instr.Label))
                {
                    Emit($"{instr.Label}");
                }
                NormalizeAndTranslate(instr);
            }
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.JMP:
                    Emit($"        JP {instr.Operands[0].Value}");
                    break;
                case OpCode.JZ:
                    Emit($"        JR Z, {instr.Operands[0].Value}");
                    break;
                case OpCode.JNZ:
                    Emit($"        JR NZ, {instr.Operands[0].Value}");
                    break;
                case OpCode.JE:
                    Emit($"        JR Z, {instr.Operands[0].Value}");
                    break;
                case OpCode.JNE:
                    Emit($"        JR NZ, {instr.Operands[0].Value}");
                    break;
                case OpCode.HALT:
                    Emit("        HALT");
                    break;
                case OpCode.NOP:
                    Emit("        NOP");
                    break;
                case OpCode.STI:
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit($"        LD A, {instr.Operands[0].Value}");
                    Emit("        RST 00H");
                    break;
                case OpCode.CATCH:
                    Emit($"        ; Set interrupt handler: {instr.Operands[0].Value}");
                    Emit("        ; Configure IM mode and vector table");
                    break;
                case OpCode.ENDCATCH:
                    break;

                // 浮点运算指令 (Z80 无硬件浮点，使用软浮点库或 ZX Spectrum ROM)
                case OpCode.FADD:
                    Emit("        ; FADD - 谯用软浮点加法库");
                    Emit("        CALL FP_ADD");
                    break;
                case OpCode.FSUB:
                    Emit("        ; FSUB - 谯用软浮点减法库");
                    Emit("        CALL FP_SUB");
                    break;
                case OpCode.FMUL:
                    Emit("        ; FMUL - 谯用软浮点乘法库");
                    Emit("        CALL FP_MUL");
                    break;
                case OpCode.FDIV:
                    Emit("        ; FDIV - 谯用软浮点除法库");
                    Emit("        CALL FP_DIV");
                    break;
                case OpCode.FNEG:
                    Emit("        ; FNEG - 符号位取反");
                    Emit("        LD A, (FP_SIGN)");
                    Emit("        XOR 80H");
                    Emit("        LD (FP_SIGN), A");
                    break;
                case OpCode.FCMP:
                    Emit("        ; FCMP - 谯用软浮点比较库");
                    Emit("        CALL FP_CMP");
                    break;

                // 浮点类型转换
                case OpCode.I2F:
                    Emit("        CALL FP_I2F");
                    break;
                case OpCode.F2I:
                    Emit("        CALL FP_F2I");
                    break;
                case OpCode.F2D:
                    Emit("        ; 单精度转双精度 (ZX Spectrum: 5字节浮点)");
                    Emit("        CALL FP_EXTEND");
                    break;
                case OpCode.D2F:
                    Emit("        ; 双精度转单精度");
                    Emit("        CALL FP_TRUNC");
                    break;

                // 浮点数据传输
                case OpCode.MOVEF:
                                // MOVEF store path: dest != REGISTER → FSTORE (handled via goto from MOVEF above)
                                case OpCode.FPUSH:
                    Emit("        CALL FP_PUSH");
                    break;
                case OpCode.FPOP:
                    Emit("        CALL FP_POP");
                    break;

                // 算术指令 (Z80 无 32 位硬件，用 IX 作为操作数指针)
                case OpCode.MUL:
                    Emit("        ; MUL - 32位乘法，通过 IX 指向操作数");
                    Emit("        LD IX, (HL)");
                    Emit("        LD E, (IX+0)");
                    Emit("        LD D, (IX+1)");
                    Emit("        LD C, (IX+2)");
                    Emit("        LD B, (IX+3)");
                    Emit("        CALL MUL32");
                    break;
                case OpCode.DIV:
                    Emit("        ; DIV - 32位除法");
                    Emit("        CALL DIV32");
                    break;
                case OpCode.MOD:
                    Emit("        ; MOD - 32位模除");
                    Emit("        CALL MOD32");
                    break;
                case OpCode.INC:
                    Emit($"        ; INC - 增加 IX 指向的32位数");
                    Emit("        INC (IX+0)");
                    Emit("        JR NZ, INC_DONE");
                    Emit("        INC (IX+1)");
                    Emit("        JR NZ, INC_DONE");
                    Emit("        INC (IX+2)");
                    Emit("        JR NZ, INC_DONE");
                    Emit("        INC (IX+3)");
                    Emit("INC_DONE:");
                    break;
                case OpCode.DEC:
                    Emit($"        ; DEC - 减少 IX 指向的32位数");
                    Emit("        LD A, (IX+0)");
                    Emit("        DEC A");
                    Emit("        LD (IX+0), A");
                    Emit("        JR NZ, DEC_DONE");
                    Emit("        LD A, (IX+1)");
                    Emit("        DEC A");
                    Emit("        LD (IX+1), A");
                    Emit("        JR NZ, DEC_DONE");
                    Emit("        LD A, (IX+2)");
                    Emit("        DEC A");
                    Emit("        LD (IX+2), A");
                    Emit("        JR NZ, DEC_DONE");
                    Emit("        LD A, (IX+3)");
                    Emit("        DEC A");
                    Emit("        LD (IX+3), A");
                    Emit("DEC_DONE:");
                    break;
                case OpCode.NEG:
                    Emit("        ; NEG - 32位数取反");
                    Emit("        LD A, (HL)");
                    Emit("        NEG");
                    Emit("        LD (HL), A");
                    Emit("        INC HL");
                    Emit("        LD A, (HL)");
                    Emit("        CPL");
                    Emit("        ADC A, 0");
                    Emit("        LD (HL), A");
                    Emit("        INC HL");
                    Emit("        LD A, (HL)");
                    Emit("        CPL");
                    Emit("        ADC A, 0");
                    Emit("        LD (HL), A");
                    Emit("        INC HL");
                    Emit("        LD A, (HL)");
                    Emit("        CPL");
                    Emit("        ADC A, 0");
                    Emit("        LD (HL), A");
                    break;

                // 逻辑指令
                case OpCode.AND:
                    Emit("        CALL AND32");
                    break;
                case OpCode.OR:
                    Emit("        CALL OR32");
                    break;
                case OpCode.XOR:
                    Emit("        CALL XOR32");
                    break;
                case OpCode.NOT:
                    Emit("        ; NOT - HL 指向的字节取反");
                    Emit("        LD A, (HL)");
                    Emit("        CPL");
                    Emit("        LD (HL), A");
                    break;
                case OpCode.TEST:
                    Emit("        ; TEST - 测试 HL 指向的值是否为零");
                    Emit("        LD A, (HL)");
                    Emit("        OR (HL)");
                    Emit("        JR Z, TEST_Z");
                    Emit("TEST_Z:");
                    Emit("        ; Z flag set if zero");
                    break;

                // 位移指令
                case OpCode.SHL:
                    Emit("        ; SHL - 32位左移");
                    Emit("        CALL SHL32");
                    break;
                case OpCode.SHR:
                    Emit("        ; SHR - 32位逻辑右移");
                    Emit("        CALL SHR32");
                    break;

                // 栈和函数调用指令
                case OpCode.PUSH:
                    Emit($"        PUSH {instr.Operands[0].Value}");
                    break;
                case OpCode.POP:
                    Emit($"        POP {instr.Operands[0].Value}");
                    break;
                case OpCode.CALL:
                    Emit($"        CALL {instr.Operands[0].Value}");
                    break;
                case OpCode.RET:
                    Emit("        RET");
                    break;
                // case OpCode.RET_VAL:
                //     Emit("        ; RET_VAL - 返回值已在 A");
                //     Emit("        RET");
                //     break;

                // 标签指令
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;

                // 比较跳转指令
                case OpCode.JL:
                    Emit($"        ; JL - 带符号小于跳转");
                    Emit("        CALL CMP32");
                    Emit($"        JP M, {instr.Operands[0].Value}");
                    break;
                case OpCode.JLE:
                    Emit($"        ; JLE - 带符号小于等于跳转");
                    Emit("        CALL CMP32");
                    Emit($"        JP PE, {instr.Operands[0].Value}");
                    Emit($"        JP Z, {instr.Operands[0].Value}");
                    break;
                case OpCode.JG:
                    Emit($"        ; JG - 带符号大于跳转");
                    Emit("        CALL CMP32");
                    Emit($"        JP PO, {instr.Operands[0].Value}");
                    Emit($"        JP NZ, {instr.Operands[0].Value}");
                    break;
                case OpCode.JGE:
                    Emit($"        ; JGE - 带符号大于等于跳转");
                    Emit("        CALL CMP32");
                    Emit($"        JP PO, {instr.Operands[0].Value}");
                    break;

                // 系统调用 (ALLOC/FREE 通过 SYSCALL 40/41)
                case OpCode.SYSCALL:
                    Emit($"        ; SYSCALL {instr.Operands[0].Value}");
                    Emit("        CALL SYSCALL_HANDLER");
                    break;

                // 栈帧管理
                case OpCode.ENTER:
                    {
                        int size = int.Parse(instr.Operands[0].Value.ToString());
                        Emit("        ; ENTER: PUSH BP; MOVE BP,SP; SUB SP,size");
                        Emit("        PUSH BC");
                        Emit("        LD BC, SP");
                        Emit("        PUSH BC");
                        if (size > 0)
                            Emit($"        ; SUB SP, {size}");
                    }
                    break;
                case OpCode.LEAVE:
                    Emit("        ; LEAVE: MOVE SP,BP; POP BP");
                    Emit("        POP BC");
                    Emit("        LD SP, BC");
                    Emit("        POP BC");
                    break;

                // 标志位控制
                case OpCode.CLC:
                    Emit("        AND A");
                    break;
                case OpCode.STC:
                    Emit("        SCF");
                    break;

                // 内联汇编
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode

                // 地址计算
                                // 8位数据传输
                                                                                case OpCode.MOVEB:
                    {
                        var dst = instr.Operands[0];
                        var src = instr.Operands[1];
                        if (dst.Type == OperandType.REGISTER && src.Type == OperandType.REGISTER)
                        {
                            int dstReg = (int)dst.Value;
                            int srcReg = (int)src.Value;
                            string dstOffset = GetRegOffset(dstReg);
                            string srcOffset = GetRegOffset(srcReg);
                            Emit($"        ; MOVEB R{dstReg}, R{srcReg} (8-bit)");
                            Emit($"        LD A, ({VR_BASE}+{srcOffset})");
                            Emit($"        LD ({VR_BASE}+{dstOffset}), A");
                        }
                    }
                    break;
                case OpCode.MOVEH:
                    {
                        var dst = instr.Operands[0];
                        var src = instr.Operands[1];
                        if (dst.Type == OperandType.REGISTER && src.Type == OperandType.REGISTER)
                        {
                            int dstReg = (int)dst.Value;
                            int srcReg = (int)src.Value;
                            string dstOffset = GetRegOffset(dstReg);
                            string srcOffset = GetRegOffset(srcReg);
                            Emit($"        ; MOVEW R{dstReg}, R{srcReg} (16-bit)");
                            Emit("        LD HL, " + VR_BASE + "+" + srcOffset);
                            Emit("        LD DE, " + VR_BASE + "+" + dstOffset);
                            Emit("        LD BC, 2");
                            Emit("        LDIR");
                        }
                    }
                    break;
                case OpCode.PUSHB:
                    {
                        var src = instr.Operands[0];
                        if (src.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)src.Value;
                            string offset = GetRegOffset(regNum);
                            Emit($"        ; PUSHB R{regNum} (8-bit)");
                            Emit($"        LD A, ({VR_BASE}+{offset})");
                            Emit("        PUSH AF");
                        }
                    }
                    break;
                case OpCode.PUSHH:
                    {
                        var src = instr.Operands[0];
                        if (src.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)src.Value;
                            string offset = GetRegOffset(regNum);
                            Emit($"        ; PUSHW R{regNum} (16-bit)");
                            Emit("        LD HL, " + VR_BASE + "+" + offset);
                            Emit("        LD A, (HL)");
                            Emit("        INC HL");
                            Emit("        LD H, (HL)");
                            Emit("        LD L, A");
                            Emit("        PUSH HL");
                        }
                    }
                    break;
                case OpCode.POPB:
                    {
                        var dst = instr.Operands[0];
                        if (dst.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)dst.Value;
                            string offset = GetRegOffset(regNum);
                            Emit($"        ; POPB R{regNum} (8-bit, zero-extend)");
                            Emit("        POP AF");
                            Emit("        PUSH HL");
                            Emit($"        LD HL, {VR_BASE}+{offset}");
                            Emit("        LD (HL), A");
                            Emit("        INC HL");
                            Emit("        XOR A");
                            Emit("        LD (HL), A");
                            Emit("        INC HL");
                            Emit("        LD (HL), A");
                            Emit("        INC HL");
                            Emit("        LD (HL), A");
                            Emit("        POP HL");
                        }
                    }
                    break;
                case OpCode.POPH:
                    {
                        var dst = instr.Operands[0];
                        if (dst.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)dst.Value;
                            string offset = GetRegOffset(regNum);
                            Emit($"        ; POPW R{regNum} (16-bit, zero-extend)");
                            Emit("        POP HL");
                            Emit("        PUSH HL");
                            Emit("        PUSH DE");
                            Emit("        PUSH BC");
                            Emit($"        LD DE, {VR_BASE}+{offset}");
                            Emit("        LD BC, 2");
                            Emit("        LDIR");
                            Emit("        POP BC");
                            Emit("        POP DE");
                            Emit("        POP HL");
                            Emit("        ; zero-extend upper 16 bits");
                            Emit("        PUSH HL");
                            Emit("        INC DE");
                            Emit("        XOR A");
                            Emit("        LD (DE), A");
                            Emit("        INC DE");
                            Emit("        LD (DE), A");
                            Emit("        POP HL");
                        }
                    }
                    break;

                // 调试
                case OpCode.BREAK:
                    Emit("        RST 38H");
                    break;

                case OpCode.ZERO:
                    {
                        string off = GetRegOffset((int)instr.Operands[0].Value);
                        Emit($"        LD HL, {off}");
                        Emit($"        LD B, 4");
                        Emit("        XOR A");
                        Emit("        LD (HL), A");
                        Emit("        INC HL");
                        Emit("        LD (HL), A");
                        Emit("        INC HL");
                        Emit("        LD (HL), A");
                        Emit("        INC HL");
                        Emit("        LD (HL), A");
                    }
                    break;
                case OpCode.SHLV:
                    Emit("        CALL SHL32");
                    break;
                case OpCode.SHRV:
                    Emit("        CALL SHR32");
                    break;
                case OpCode.I2D:
                case OpCode.D2I:
                    Emit($"        CALL FP_OP     ; {instr.Opcode}: {string.Join(", ", instr.Operands)}");
                    break;

                // 符号扩展/条件移动/循环移位 (v1.66.28+) — 软件库
                case OpCode.SEXTB: case OpCode.SEXTH:
                case OpCode.CMOVZ: case OpCode.CMOVNZ:
                case OpCode.ROL: case OpCode.ROR:
                    Emit($"        CALL __{instr.Opcode.ToString().ToLower()}");
                    break;

                default:
                    Emit($"        ; UNIMPLEMENTED: {instr.Opcode.ToString()} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];
            int regNum = (int)dst.Value;
            string offset = GetRegOffset(regNum);

            Emit($"        ; LOAD R{regNum}, src (32-bit)");

            // 保存寄存器
            Emit("        PUSH HL");
            Emit("        PUSH BC");
            Emit("        PUSH DE");

            // 计算目标地址
            Emit($"        LD HL, {VR_BASE}+{offset}");

            if (src.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src);
                Emit($"        LD (HL), ${value       & 0xFF:X2}");
                Emit("        INC HL");
                Emit($"        LD (HL), ${(value >> 8) & 0xFF:X2}");
                Emit("        INC HL");
                Emit($"        LD (HL), ${(value >> 16) & 0xFF:X2}");
                Emit("        INC HL");
                Emit($"        LD (HL), ${(value >> 24) & 0xFF:X2}");
            }
            else if (src.Type == OperandType.MEMORY)
            {
                string addr = src.Value.ToString();
                Emit($"        LD DE, {addr}");
                Emit("        LD BC, 4");
                Emit("        LDIR");  // 块复制4字节
            }
            else if (src.Type == OperandType.REGISTER)
            {
                int srcReg = (int)src.Value;
                string srcOffset = GetRegOffset(srcReg);
                Emit($"        LD DE, {VR_BASE}+{srcOffset}");
                Emit("        LD BC, 4");
                Emit("        LDIR");
            }
            else if (src.Type == OperandType.INDIRECT)
            {
                string ptr = src.Value.ToString();
                Emit($"        LD DE, ({ptr})");  // 从指针地址读取
                Emit("        LD BC, 4");
                Emit("        EX DE, HL");
                Emit("        LDIR");
            }

            // 恢复寄存器
            Emit("        POP DE");
            Emit("        POP BC");
            Emit("        POP HL");
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            Emit("        ; STORE");
            Emit("        PUSH HL");
            Emit("        PUSH DE");
            Emit("        PUSH BC");

            if (src.Type == OperandType.REGISTER)
            {
                int srcReg = (int)src.Value;
                string srcOffset = GetRegOffset(srcReg);

                if (dst.Type == OperandType.MEMORY)
                {
                    string addr = dst.Value.ToString();
                    Emit($"        LD HL, {VR_BASE}+{srcOffset}");
                    Emit($"        LD DE, {addr}");
                    Emit("        LD BC, 4");
                    Emit("        LDIR");
                }
                else if (dst.Type == OperandType.INDIRECT)
                {
                    string ptr = dst.Value.ToString();
                    Emit($"        LD HL, {VR_BASE}+{srcOffset}");
                    Emit($"        LD DE, ({ptr})");
                    Emit("        LD BC, 4");
                    Emit("        LDIR");
                }
                else if (dst.Type == OperandType.REGISTER)
                {
                    int dstReg = (int)dst.Value;
                    string dstOffset = GetRegOffset(dstReg);
                    Emit($"        LD HL, {VR_BASE}+{srcOffset}");
                    Emit($"        LD DE, {VR_BASE}+{dstOffset}");
                    Emit("        LD BC, 4");
                    Emit("        LDIR");
                }
            }
            else if (src.Type == OperandType.MEMORY)
            {
                // 从内存加载再存储到内存
                string srcAddr = src.Value.ToString();
                if (dst.Type == OperandType.MEMORY)
                {
                    string dstAddr = dst.Value.ToString();
                    Emit($"        LD DE, {dstAddr}");
                    Emit($"        LD HL, {srcAddr}");
                    Emit("        LD BC, 4");
                    Emit("        LDIR");
                }
            }

            Emit("        POP BC");
            Emit("        POP DE");
            Emit("        POP HL");
        }

        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            Emit("        ; 32-bit ADD (with carry chain)");
            Emit("        PUSH HL");
            Emit("        PUSH DE");
            Emit("        PUSH BC");
            Emit("        PUSH IX");

            string dstOffset = GetRegOffset((int)dst.Value);
            string src1Offset = GetRegOffset((int)src1.Value);

            // 使用 IX 指向结果
            Emit($"        LD IX, {VR_BASE}+{dstOffset}");
            // 使用 HL 指向源1
            Emit($"        LD HL, {VR_BASE}+{src1Offset}");

            if (src2.Type == OperandType.REGISTER)
            {
                string src2Offset = GetRegOffset((int)src2.Value);
                Emit($"        LD DE, {VR_BASE}+{src2Offset}");
                // 逐字节加法
                Emit("        OR A");  // 清除进位
                Emit("        LD A, (HL)");
                Emit("        ADC A, (DE)");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC DE");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit("        ADC A, (DE)");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC DE");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit("        ADC A, (DE)");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC DE");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit("        ADC A, (DE)");
                Emit("        LD (IX), A");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit("        OR A");  // 清除进位
                Emit("        LD A, (HL)");
                Emit($"        ADC A, ${value       & 0xFF:X2}");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit($"        ADC A, ${(value >> 8) & 0xFF:X2}");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit($"        ADC A, ${(value >> 16) & 0xFF:X2}");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit($"        ADC A, ${(value >> 24) & 0xFF:X2}");
                Emit("        LD (IX), A");
            }

            Emit("        POP IX");
            Emit("        POP BC");
            Emit("        POP DE");
            Emit("        POP HL");
        }

        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            Emit("        ; 32-bit SUB (with borrow chain)");
            Emit("        PUSH HL");
            Emit("        PUSH DE");
            Emit("        PUSH BC");
            Emit("        PUSH IX");

            string dstOffset = GetRegOffset((int)dst.Value);
            string src1Offset = GetRegOffset((int)src1.Value);

            // 使用 IX 指向结果
            Emit($"        LD IX, {VR_BASE}+{dstOffset}");
            // 使用 HL 指向源1
            Emit($"        LD HL, {VR_BASE}+{src1Offset}");

            if (src2.Type == OperandType.REGISTER)
            {
                string src2Offset = GetRegOffset((int)src2.Value);
                Emit($"        LD DE, {VR_BASE}+{src2Offset}");
                // 逐字节减法
                Emit("        OR A");  // 清除进位（借位）
                Emit("        LD A, (HL)");
                Emit("        SBC A, (DE)");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC DE");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit("        SBC A, (DE)");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC DE");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit("        SBC A, (DE)");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC DE");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit("        SBC A, (DE)");
                Emit("        LD (IX), A");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit("        OR A");
                Emit("        LD A, (HL)");
                Emit($"        SBC A, ${value       & 0xFF:X2}");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit($"        SBC A, ${(value >> 8) & 0xFF:X2}");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit($"        SBC A, ${(value >> 16) & 0xFF:X2}");
                Emit("        LD (IX), A");
                Emit("        INC HL");
                Emit("        INC IX");
                Emit("        LD A, (HL)");
                Emit($"        SBC A, ${(value >> 24) & 0xFF:X2}");
                Emit("        LD (IX), A");
            }

            Emit("        POP IX");
            Emit("        POP BC");
            Emit("        POP DE");
            Emit("        POP HL");
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];

            Emit("        ; 32-bit CMP");
            Emit("        PUSH HL");
            Emit("        PUSH DE");

            string src1Offset = GetRegOffset((int)src1.Value);
            Emit($"        LD HL, {VR_BASE}+{src1Offset}");

            if (src2.Type == OperandType.REGISTER)
            {
                string src2Offset = GetRegOffset((int)src2.Value);
                Emit($"        LD DE, {VR_BASE}+{src2Offset}");
                // 从高位开始比较
                Emit("        PUSH AF");
                Emit("        LD A, (HL+3)");
                Emit("        SUB (DE+3)");
                Emit("        JR NZ, .cmp_done");
                Emit("        LD A, (HL+2)");
                Emit("        SUB (DE+2)");
                Emit("        JR NZ, .cmp_done");
                Emit("        LD A, (HL+1)");
                Emit("        SUB (DE+1)");
                Emit("        JR NZ, .cmp_done");
                Emit("        LD A, (HL)");
                Emit("        SUB (DE)");
                Emit(".cmp_done:");
                Emit("        POP AF");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit("        PUSH AF");
                Emit("        LD A, (HL+3)");
                Emit($"        CP ${(value >> 24) & 0xFF:X2}");
                Emit("        JR NZ, .cmp_done");
                Emit("        LD A, (HL+2)");
                Emit($"        CP ${(value >> 16) & 0xFF:X2}");
                Emit("        JR NZ, .cmp_done");
                Emit("        LD A, (HL+1)");
                Emit($"        CP ${(value >> 8) & 0xFF:X2}");
                Emit("        JR NZ, .cmp_done");
                Emit("        LD A, (HL)");
                Emit($"        CP ${value       & 0xFF:X2}");
                Emit(".cmp_done:");
                Emit("        POP AF");
            }

            Emit("        POP DE");
            Emit("        POP HL");
        }

        protected override string MapRegister(int regNum)
        {
            return REGISTER_MAP.TryGetValue(regNum, out string reg) ? reg : $"R{regNum}";
        }
    }
}
